def main():
    kok = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    out = [{"k": k, "s": s, "c": c, "a": a} for k, s, c, a in S]
    for q in out:
        assert len(q["c"]) == 4 and len(set(q["c"])) == 4, q["s"]
    json.dump(out, open(os.path.join(kok, "data", "sorular.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=0)
    from collections import Counter
    print(len(out), "soru", dict(Counter(q["k"] for q in out)))

if __name__ == "__main__":
    main()
